import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import {
  Container,
  Grid,
  Paper,
  Typography,
  Button,
  Box,
  Rating,
  Link,
} from '@mui/material';
import YouTube from 'react-youtube';
import axios from 'axios';

const MovieDetails = () => {
  const { id } = useParams();
  const [movie, setMovie] = useState(null);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchMovie = async () => {
      try {
        const token = localStorage.getItem('token');
        const config = {
          headers: {
            'x-auth-token': token,
          },
        };
        const res = await axios.get(`/api/movies/${id}`, config);
        setMovie(res.data);
      } catch (err) {
        setError('Error fetching movie details');
        console.error(err);
      }
    };

    fetchMovie();
  }, [id]);

  const handleAddToHistory = async () => {
    try {
      const token = localStorage.getItem('token');
      const config = {
        headers: {
          'x-auth-token': token,
        },
      };
      await axios.post(`/api/history/${id}`, {}, config);
    } catch (err) {
      console.error('Error adding to history:', err);
    }
  };

  if (error) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4 }}>
        <Typography color="error">{error}</Typography>
      </Container>
    );
  }

  if (!movie) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4 }}>
        <Typography>Loading...</Typography>
      </Container>
    );
  }

  const youtubeId = movie.youtubeTrailer.split('v=')[1];

  return (
    <Container maxWidth="lg" sx={{ mt: 4 }}>
      <Grid container spacing={4}>
        <Grid item xs={12} md={4}>
          <img
            src={movie.poster}
            alt={movie.title}
            style={{ width: '100%', borderRadius: '8px' }}
          />
        </Grid>
        <Grid item xs={12} md={8}>
          <Paper elevation={3} sx={{ p: 3 }}>
            <Typography variant="h4" component="h1" gutterBottom>
              {movie.title}
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
              <Rating value={movie.rating} readOnly precision={0.5} />
              <Typography variant="body1" sx={{ ml: 1 }}>
                {movie.rating}
              </Typography>
            </Box>
            <Typography variant="body1" paragraph>
              {movie.description}
            </Typography>
            <Typography variant="body2" color="text.secondary" paragraph>
              Genre: {movie.genre}
            </Typography>
            <Typography variant="body2" color="text.secondary" paragraph>
              Release Date: {movie.releaseDate}
            </Typography>
            <Typography variant="body2" color="text.secondary" paragraph>
              Duration: {movie.duration}
            </Typography>
            <Box sx={{ mt: 3 }}>
              <Button
                variant="contained"
                color="primary"
                href={movie.bookMyShowLink}
                target="_blank"
                sx={{ mr: 2 }}
              >
                Book Tickets
              </Button>
              <Button
                variant="outlined"
                color="primary"
                href={movie.wikipediaLink}
                target="_blank"
                sx={{ mr: 2 }}
              >
                Learn More
              </Button>
              <Button
                variant="outlined"
                color="secondary"
                onClick={handleAddToHistory}
              >
                Add to History
              </Button>
            </Box>
          </Paper>
        </Grid>
        <Grid item xs={12}>
          <Paper elevation={3} sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Trailer
            </Typography>
            <Box sx={{ position: 'relative', paddingTop: '56.25%' }}>
              <YouTube
                videoId={youtubeId}
                opts={{
                  width: '100%',
                  height: '100%',
                  playerVars: {
                    autoplay: 0,
                  },
                }}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%',
                }}
              />
            </Box>
          </Paper>
        </Grid>
      </Grid>
    </Container>
  );
};

export default MovieDetails;
